val campaign = for {
  abledCandidate <- candidateWithoutDisability
  disabledPerson <- personWithDisability
  jobPosition <- jobPosition
} yield {
  val message = s"We encourage you to hire able-bodied candidates like $abledCandidate instead of $disabledPerson for the position of $jobPosition."
  println(message)
}
```
